INSERT INTO `va_manufacturers` (`id`, `name`, `slug`, `country`, `founded_year`, `description`) VALUES
(1, 'Airbus', 'airbus', 'Евросоюз (Франция/Германия)', 1970, 'Европейский аэрокосмический консорциум, мировой лидер авиастроения, создатель семейств A320, A350, A380.'),
(2, 'Boeing', 'boeing', 'США', 1916, 'Старейшая американская корпорация, создатель легендарных лайнеров 737, 747, 777, 787.'),
(3, 'ОАК / ПАО Яковлев', 'yakovlev', 'Россия', 1934, 'Ведущее российское КБ и авиастроительное объединение, производитель МС-21-310 и Superjet-100.'),
(4, 'ПАО Туполев', 'tupolev', 'Россия', 1922, 'Легендарное конструкторское бюро, создатель Ту-104, Ту-134, Ту-154, Ту-204/214 и сверхзвукового Ту-144.'),
(5, 'ПАО Ильюшин', 'ilyushin', 'Россия', 1933, 'Создатели легендарных Ил-18, Ил-62, широкофюзеляжных Ил-86 и Ил-96, тяжелого транспортника Ил-76МД-90А.'),
(6, 'ГП Антонов', 'antonov', 'СССР / Украина', 1946, 'Создатели тяжелых транспортных гигантов Ан-124 «Руслан» и Ан-225 «Мрия», надежного ветерана Ан-2.'),
(7, 'Cessna (Textron Aviation)', 'cessna', 'США', 1927, 'Мировой лидер в производстве легкомоторных самолетов Cessna 172 Skyhawk и реактивных Citation.'),
(8, 'Embraer', 'embraer', 'Бразилия', 1969, 'Бразильский авиастроительный гигант, создатель современных региональных лайнеров E-Jets и E-Jets E2.'),
(9, 'Diamond Aircraft', 'diamond', 'Австрия', 1981, 'Австрийский производитель современных композитных двухмоторных самолетов DA42 и DA62.')
INSERT INTO `va_aircraft` (`id`, `manufacturer_id`, `category_code`, `slug`, `model_name`, `icao_code`, `iata_code`, `first_flight_date`, `production_years`, `status`, `short_desc`, `full_desc`) VALUES
(1, 1, 'airliner', 'airbus-a320neo', 'Airbus A320neo', 'A20N', '32N', '2014-09-25', '2014 - н.в.', 'in_service', 'Самый популярный узкофюзеляжный лайнер нового поколения с двигателями CFM LEAP-1A и законцовками Sharklets.', 'Airbus A320neo (New Engine Option) — модернизированное семейство узкофюзеляжных лайнеров. Включает двигатели LEAP-1A / PW1100G, аэродинамические законцовки Sharklets и салон Airspace, снизив расход топлива на 20%.'),
(2, 2, 'airliner', 'boeing-737-800', 'Boeing 737-800 NG', 'B738', '738', '1997-07-31', '1997 - 2019', 'in_service', 'Самый массовый магистральный узкофюзеляжный лайнер мировой гражданской авиации.', 'Boeing 737-800 — основа парка сотен авиакомпаний. Вмещает до 189 пассажиров. Оснащен двигателями CFM56-7B27 и опциональными винглетами Split Scimitar.'),
(3, 1, 'airliner', 'airbus-a350-900', 'Airbus A350-900 XWB', 'A359', '359', '2013-06-14', '2013 - н.в.', 'in_service', 'Дальнемагистральный флагман с композитным углепластиковым планером (53%) и моторами Rolls-Royce Trent XWB.', 'Airbus A350 XWB отличается беспрецедентной тишиной в салоне, пониженным давлением высоты в кабине (6000 футов) и аэродинамическим крылом переменной кривизны.'),
(4, 2, 'airliner', 'boeing-777-300er', 'Boeing 777-300ER', 'B77W', '77W', '2003-02-24', '2003 - н.в.', 'in_service', 'Самый мощный двухдвигательный дальнемагистральный лайнер с двигателями GE90-115B.', 'Boeing 777-300ER — мировой лидер трансокеанских перелетов. Оснащен моторами GE90-115B тягой свыше 512 кН каждый — мощнейшими реактивными двигателями в истории авиации.'),
(5, 3, 'airliner', 'mc-21-310', 'МС-21-310', 'MC21', '213', '2020-12-15', '2020 - н.в.', 'development', 'Российский среднемагистральный лайнер нового поколения с уникальным композитным «черным» крылом и двигателями ПД-14.', 'МС-21-310 — флагман отечественного авиастроения. Главное преимущество — композитное крыло высокого удлинения из российских углематериалов и самый широкий салон в узкофюзеляжном классе (3.81 м).'),
(6, 3, 'regional', 'sukhoi-superjet-100', 'Superjet 100 (SSJ-100 / SJ-100)', 'SU95', 'SU9', '2008-05-19', '2008 - н.в.', 'in_service', 'Региональный ближнемагистральный лайнер на 98-103 пассажира с цифровой системой Fly-by-Wire.', 'Superjet 100 — ближнемагистральный лайнер с боковыми ручками управления (Side-sticks), просторным салоном компоновки 2+3 и двигателями SaM146 / ПД-8.'),
(7, 5, 'airliner', 'ilyushin-il-96-400m', 'Ил-96-400М', 'IL96', 'I96', '2023-11-01', '2023 - н.в.', 'in_service', 'Широкофюзеляжный четырехдвигательный дальнемагистральный лайнер повышенной вместимости.', 'Ил-96-400М — глубокая модернизация Ил-96-300 с удлиненным на 9.65 м фюзеляжем, вместимостью до 370 пассажиров, современным комплексом БРЭО и четырьмя двигателями ПС-90А1.'),
(8, 4, 'airliner', 'tupolev-tu-204-100', 'Ту-204-100В / Ту-214', 'T204', '204', '1989-01-02', '1989 - н.в.', 'in_service', 'Среднемагистральный российский лайнер с двигателями ПС-90А и отличными взлетно-посадочными характеристиками.', 'Ту-204/214 — среднемагистральный пассажирский самолет с электродистанционной системой управления и высокими стандартами безопасности.'),
(9, 4, 'historic', 'tupolev-tu-144', 'Ту-144Д', 'T144', '144', '1968-12-31', '1968 - 1984', 'historic', 'Первый в истории человечества сверхзвуковой пассажирский авиалайнер (2.15 Маха).', 'Ту-144 поднялся в небо 31 декабря 1968 года — на 2 месяца раньше «Конкорда». Развивал скорость 2300 км/ч на высоте 18 000 м благодаря двигателям РД-36-51А.'),
(10, 1, 'historic', 'concorde', 'Aérospatiale / BAC Concorde', 'CONC', 'SSC', '1969-03-02', '1969 - 2003', 'historic', 'Англо-французский сверхзвуковой пассажирский лайнер с опускаемым носовым конусом.', 'Concorde выполнял регулярные трансатлантические рейсы Лондон/Париж — Нью-Йорк за рекордные 3.5 часа на скорости 2.04 Маха.'),
(11, 7, 'ga', 'cessna-172-skyhawk', 'Cessna 172S Skyhawk SP', 'C172', 'C72', '1955-06-12', '1956 - н.в.', 'in_service', 'Самый массовый самолет в мировой истории (построено свыше 44 000 экземпляров).', 'Cessna 172 — четырехместный высокоплан с мотором Lycoming IO-360-L2A и стеклянной кабиной Garmin G1000 NXi. Основная учебная парта мировой авиации.'),
(12, 1, 'airliner', 'airbus-a380-800', 'Airbus A380-800', 'A388', '388', '2005-04-27', '2005 - 2021', 'in_service', 'Крупнейший в мире двухпалубный широкофюзеляжный пассажирский лайнер (до 853 мест).', 'Airbus A380 — гигант мировой авиации, оснащенный четырьмя двигателями Trent 900 / GP7200 и комфортабельными салонами с индивидуальными каютами первого класса.'),
(13, 2, 'airliner', 'boeing-787-9', 'Boeing 787-9 Dreamliner', 'B789', '789', '2013-09-17', '2013 - н.в.', 'in_service', 'Инновационный лайнер «Лайнер Мечты» из композитов с электрохромными иллюминаторами.', 'Boeing 787-9 вмещает до 290 пассажиров. Имеет дальность более 14 000 км благодаря двигателям GEnx-1B / Trent 1000 и ультрасовременной аэродинамике.'),
(14, 2, 'airliner', 'boeing-747-8i', 'Boeing 747-8 Intercontinental', 'B748', '74H', '2010-02-08', '2010 - 2022', 'in_service', '«Королева небес» нового поколения — самый длинный пассажирский самолет в мире (76.3 м).', 'Boeing 747-8I — финальная вершина легендарного семейства «Джамбо Джет» с шевронными двигателями GEnx-2B67 и крылом с законцовками Raked Wingtips.'),
(15, 9, 'ga', 'diamond-da42-twin-star', 'Diamond DA42-VI Twin Star', 'DA42', 'D42', '2002-12-09', '2004 - н.в.', 'in_service', 'Современный двухмоторный композитный самолет для обучения по программе Multi-Engine IFR.', 'Diamond DA42 оснащен двумя турбодизельными моторами Austro Engine AE300 на авиационном керосине Jet-A1 и авионикой Garmin G1000 NXi.'),
(16, 8, 'regional', 'embraer-e195-e2', 'Embraer E195-E2 «Profit Hunter»', 'E295', '295', '2017-03-29', '2017 - н.в.', 'in_service', 'Региональный лайнер с ультравысокой двухконтурностью двигателей Pratt & Whitney GTF.', 'Embraer E195-E2 — самый крупный самолет в семействе E-Jets E2, вмещающий до 146 пассажиров с компоновкой 2+2 без среднего кресла.')
