INSERT INTO `va_airlines` (`name_ru`, `name_en`, `slug`, `iata`, `icao`, `callsign`, `country`, `alliance`, `fleet_size`, `founded_year`, `description`) VALUES
('Аэрофлот — Российские авиалинии', 'Aeroflot Russian Airlines', 'aeroflot', 'SU', 'AFL', 'AEROFLOT', 'Россия', 'none', 171, 1923, 'Национальный авиаперевозчик России, одна из старейших авиакомпаний мира с базовым хабом в Шереметьево.'),
('S7 Airlines (Авиакомпания «Сибирь»)', 'S7 Airlines', 's7-airlines', 'S7', 'SBI', 'SIBERIAN CODES', 'Россия', 'none', 101, 1992, 'Крупнейший частный авиаперевозчик России с ключевыми хабами в Москве (Домодедово) и Новосибирске (Толмачево).'),
('Авиакомпания «Россия»', 'Rossiya Airlines', 'rossiya', 'FV', 'SDM', 'RUSSIA', 'Россия', 'none', 135, 1934, 'Входит в Группу Аэрофлот, крупнейший эксплуатант лайнеров Superjet 100 и Boeing 777/747.'),
('Авиакомпания «Победа»', 'Pobeda Airlines', 'pobeda', 'DP', 'PBD', 'POBEDA', 'Россия', 'none', 42, 2014, 'Единственный классический российский лоукостер (LCC), эксплуатирующий монофлот современных Boeing 737-800.'),
('Авиакомпания «ЮТэйр»', 'UTair Aviation', 'utair', 'UT', 'UTA', 'UTAIR', 'Россия', 'none', 60, 1967, 'Один из старейших региональных перевозчиков Сибири и крупнейший в мире вертолетный оператор.'),
('Emirates', 'Emirates', 'emirates', 'EK', 'UAE', 'EMIRATES', 'ОАЭ', 'none', 260, 1985, 'Мировой гигант премиальных дальнемагистральных перевозок, крупнейший оператор Airbus A380 и Boeing 777.'),
('Qatar Airways', 'Qatar Airways', 'qatar-airways', 'QR', 'QTR', 'QATARI', 'Катар', 'oneworld', 235, 1993, 'Многократный обладатель награды Skytrax «Лучшая авиакомпания мира» со сверхсовременным флотом A350 и B787.'),
('Turkish Airlines', 'Turkish Airlines', 'turkish-airlines', 'TK', 'THY', 'TURKISH', 'Турция', 'star_alliance', 430, 1933, 'Флагман Турции, летающий в рекордное число стран и аэропортов по всему миру через мегахаб в Стамбуле.'),
('Lufthansa', 'Lufthansa', 'lufthansa', 'LH', 'DLH', 'LUFTHANSA', 'Германия', 'star_alliance', 280, 1953, 'Крупнейший авиационный концерн Европы со штаб-квартирой во Франкфурте-на-Майне.'),
('Singapore Airlines', 'Singapore Airlines', 'singapore-airlines', 'SQ', 'SIA', 'SINGAPORE', 'Сингапур', 'star_alliance', 150, 1947, 'Эталон сервиса мировой авиации, первый в истории эксплуатант гиганта Airbus A380.')
INSERT INTO `va_engines` (`model_name`, `manufacturer`, `type`, `thrust_max_kn`, `bypass_ratio`, `dry_weight_kg`, `description`) VALUES
('GE90-115B', 'General Electric', 'turbofan', 512.9, 8.70, 8283, 'Самый мощный турбовентиляторный двигатель в истории коммерческой авиации. Устанавливается на Boeing 777-300ER.'),
('CFM LEAP-1A', 'CFM International', 'turbofan', 143.0, 11.00, 2990, 'Высокоэффективный двигатель нового поколения с полыми лопатками вентилятора 3D RTM из углеволокна для семейства Airbus A320neo.'),
('ПД-14', 'ОДК-Авиадвигатель', 'turbofan', 137.3, 8.50, 2870, 'Новейший российский двухконтурный турбовентиляторный двигатель пятого поколения для магистрального лайнера МС-21-310.'),
('Trent XWB-84', 'Rolls-Royce', 'turbofan', 374.5, 9.60, 7277, 'Один из самых тихих и экономичных трехвальных двигателей для дальнемагистрального лайнера Airbus A350-900.'),
('CFM56-7B27', 'CFM International', 'turbofan', 121.4, 5.10, 2370, 'Самый надежный и массовый авиационный двигатель в истории, рабочая лошадка всех Boeing 737 Next Generation.'),
('ПС-90А1', 'ОДК-Пермские моторы', 'turbofan', 171.0, 4.50, 3100, 'Турбовентиляторный двигатель повышенной тяги для тяжелых широкофюзеляжных лайнеров Ил-96-400М и Ил-76МД-90А.')
INSERT INTO `va_glossary` (`term`, `abbreviation`, `category`, `short_def`, `full_explanation`, `practical_example`) VALUES
('Скорость принятия решения (V1)', 'V1', 'acronym', 'Критическая скорость разбега, после которой взлет не может быть безопасно прерван.', 'V1 (Decision Speed) — скорость на разбеге, до достижения которой пилот в случае отказа двигателя обязан применить экстренное торможение (RTO). После прохождения V1 взлет обязательно продолжается.', '«80 knots... Crosscheck... V1... ROTATE!»'),
('Скорость отрыва передней стойки (Vr)', 'Vr', 'acronym', 'Скорость на разбеге, при которой пилот плавно берет штурвал на себя для создания взлетного угла.', 'Rotate Speed — расчетная скорость, при которой начинается подъем носового колеса для вывода самолета на взлетный угол атаки.', '«V1... Vr... Positive Climb... Gear Up!»'),
('Курсо-глиссадная система (КГС / ILS)', 'ILS', 'navigation', 'Радиотехническая система точного захода на посадку по курсовому и глиссадному радиомаякам.', 'Instrument Landing System состоит из Localizer (направление по оси полосы) и Glide Slope (стандартный угол снижения 3 градуса). Обеспечивает заходы по категориям CAT I, II, IIIa, IIIb, IIIc.', '«Sheremetyevo Tower, AFL102, established on ILS runway 24 Left, fully configured».'),
('Система предупреждения опасных сближений (TCAS)', 'TCAS', 'systems', 'Бортовая система контроля воздушной обстановки для предотвращения столкновений в воздухе.', 'TCAS II опрашивает транспондеры соседних бортов. При опасности выдает Traffic Advisory (TA «Traffic, Traffic») или команду уклонения Resolution Advisory (RA «Climb, Climb» / «Descend, Descend»). Указания TCAS RA обязательны к немедленному выполнению!', '«TCAS RA! I have control, climbing!»'),
('Давление приведенное к уровню моря (QNH)', 'QNH', 'weather', 'Барометрическое давление, при установке которого высотомер показывает высоту над уровнем моря.', 'QNH — стандартная установка давления ниже высоты перехода (Transition Altitude). При посадке высотомер показывает абсолютную отметку превышения аэродрома над уровнем моря.', '«QNH 1018 hectopascals, runway 24 Right in use».'),
('Давление на уровне порога ВПП (QFE)', 'QFE', 'weather', 'Барометрическое давление, при установке которого на шкале высотомера прибор показывает ноль на полосе.', 'При установке давления QFE (Query: Field Elevation) высотомер показывает относительную высоту полета над конкретным аэродромом.', '«Cleared to land runway 06, QFE 745 millimeters».'),
('Стандартное давление (QNE / 1013.25 гПа)', 'QNE', 'weather', 'Давление 1013.25 гПа (29.92 inHg), устанавливаемое выше высоты перехода для эшелонирования.', 'При пересечении эшелона перехода (Transition Level) экипаж переводит шкалу высотомеров на стандартное давление QNE (STD), чтобы все воздушные суда выдерживали единую сетку эшелонов полета (Flight Levels).', '«Passing Transition Altitude, Baro Standard Crosschecked, Flight Level 280».'),
('Правила полетов по приборам (ППП / IFR)', 'IFR', 'navigation', 'Полеты, при которых выдерживание пространственного положения и навигация ведутся по приборам.', 'Instrument Flight Rules — правила, позволяющие выполнять полеты в облаках, ночью и в сложных метеоусловиях при постоянном диспетчерском контроле.', '«AFL2134 is filed IFR to Novosibirsk, ready for pushback».'),
('Правила визуальных полетов (ПВП / VFR)', 'VFR', 'navigation', 'Полеты, при которых пилот ориентируется по естественному горизонту и наземным ориентирам.', 'Visual Flight Rules требуют строгого соблюдения метеорологических минимумов: видимость более 5 км и удаление от облаков.', '«Cessna 172 RA-01234, VFR flight to Severka, climbing 1500 feet».'),
('Вспомогательная силовая установка (ВСУ / APU)', 'APU', 'systems', 'Небольшой газотурбинный двигатель в хвосте самолета для автономного энергоснабжения.', 'Auxiliary Power Unit вырабатывает электричество и сжатый воздух для кондиционирования салона и пневмостартеров запуска маршевых двигателей на стоянке.', '«APU RUNNING, APU GEN ON, APU BLEED ON».'),
('Аварийная авиационная турбина (RAT)', 'RAT', 'systems', 'Выдвижная ветряная турбина для выработки гидравлического давления при полном обесточивании.', 'Ram Air Turbine автоматически вываливается из фюзеляжа в набегающий поток воздуха при отказе всех генераторов или двигателей, питая жизненно важные контуры управления.', '«All engines failed, RAT deployed, primary flight controls active».'),
('«Арбуз»', NULL, 'slang', 'Разговорное прозвище лайнеров компании Airbus в среде русскоязычных авиаторов.', 'Популярный сленг, основанный на фонетическом созвучии бренда Airbus.', '«Вон на второй рулежке новенький Арбуз A350 рулит на исполнительный».'),
('«Бобик»', NULL, 'slang', 'Шутливое прозвище самолетов компании Boeing (в особенности серии 737).', 'Разговорное название американских лайнеров Boeing среди пилотов и споттеров.', '«Сегодня на рейсе в Сочи у нас классический Бобик-800».')
