INSERT INTO `va_articles` (`id`, `author_id`, `category_id`, `slug`, `title`, `summary`, `content`, `cover_image`, `is_published`, `reading_time_min`, `views_count`) VALUES
(1, 1, 1, 'mc-21-composite-black-wing', 'Анатомия «Черного крыла»: почему композитное крыло МС-21 опередило мировых конкурентов', 'Подробный технический разбор технологии вакуумной инфузии, композитных материалов отечественного производства и аэродинамического удлинения крыла МС-21.', '### Революция композитов в российском авиастроении\n\nГлавное отличие лайнера **МС-21-310** от прямых конкурентов — узкофюзеляжных гигантов Airbus A320neo и Boeing 737 MAX — заключается в конструкции его несущей поверхности. МС-21 стал первым в мире среднемагистральным самолетом вместимостью около 200 кресел с крылом, полностью выполненным из полимерных композиционных материалов (ПКМ).\n\n#### Почему крыло назвали «черным»?\nУглеволоконные преформы и готовые силовые элементы из углепластика имеют характерный матово-черный цвет исходного углеродного волокна.\n\n#### Технология вакуумной инфузии\nВ отличие от традиционного автоклавного метода, требующего гигантских печей под давлением, при производстве крыла МС-21 на заводе «АэроКомпозит» в Ульяновске применяется метод безавтоклавной вакуумной инфузии (VAP / VaRTM):\n1. Сухая углеродная лента выкладывается высокоточным роботом-укладчиком.\n2. Пакет волокон помещается в герметичный вакуумный мешок.\n3. Под действием вакуума происходит равномерная пропитка связующей эпоксидной смолой с последующей полимеризацией.\n\n#### Аэродинамический выигрыш\nПрименение углепластика позволило создать крыло большого удлинения (Aspect Ratio > 11.5) с тонким аэродинамическим профилем и меньшим индуктивным сопротивлением. Это обеспечивает снижение расхода авиакеросина на **6-8%** по сравнению с металлическими аналогами той же площади.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80', 1, 7, 1420),
(2, 1, 2, 'how-fly-by-wire-works', 'Законы управления Fly-by-Wire: как бортовой компьютер удерживает самолет в полете', 'Разбор алгоритмов Normal Law, Alternate Law и Direct Law в современных электродистанционных системах управления Airbus, МС-21 и Superjet.', '### От стальных тросов к цифровым шинам данных\n\nВ классических самолетах XX века отклонение штурвала передавалось на рули высоты и элероны через механическую проводку — стальные тросы, качалки и гидроусилители. В современных лайнерах семейства Airbus (A320, A350), МС-21, Superjet 100 и Boeing 777/787 реализована концепция **Fly-by-Wire (ЭДСУ — электродистанционная система управления)**.\n\n#### Архитектура законов управления (Flight Control Laws)\n1. **Normal Law (Основной режим):**\n   - Полная защита по углам атаки (Alpha Protection) — самолет физически невозможно сорвать в сваливание взятием ручки на себя.\n   - Ограничение по перегрузкам (+2.5g / -1.0g в чистой конфигурации).\n   - Автоматическая балансировка (Auto-trimming) по тангажу.\n2. **Alternate Law (Альтернативный режим):**\n   Включается при множественных отказах датчиков скорости или вычислителей. Защита по углу атаки заменяется звуковым предупреждением о сваливании (Stall Warning).\n3. **Direct Law (Прямой режим):**\n   Рулевые поверхности отклоняются строго пропорционально перемещению сайдстика пилота, без вмешательства цифровых фильтров.', 'https://images.unsplash.com/photo-1519074069444-1ba4ea16e91f?auto=format&fit=crop&w=1200&q=80', 1, 8, 980)
INSERT INTO `va_incidents` (`id`, `slug`, `title`, `date_of_incident`, `aircraft_type`, `operator`, `flight_number`, `fatalities`, `survivors`, `summary`, `root_causes`, `lessons_learned`) VALUES
(1, 'miracle-on-the-hudson-us-airways-1549', '«Чудо на Гудзоне» — успешное приводнение Airbus A320', '2009-01-15', 'Airbus A320-214 (N106US)', 'US Airways', 'AWE1549', 0, 155, 'Через 2 минуты после взлета из Нью-Йорка лайнер столкнулся со стаей канадских казарок, что вызвало отказ обоих двигателей CFM56 на высоте 850 метров. Командир Чесли Салленбергер и второй пилот Джеффри Скайлз совершили безупречную планирующую посадку на ледяные воды реки Гудзон без человеческих жертв.', 'Массивное птичье столкновение (Bird Strike) с попаданием крупных птиц в оба двигателя одновременно на малой высоте.', 'Экипаж продемонстрировал непревзойденный уровень взаимодействия (CRM), мгновенно запустив ВСУ (APU) для сохранения электропитания и законов управления Normal Law, а также хладнокровно отказался от рискованного возврата на ВПП аэродрома Тетерборо.'),
(2, 'gimli-glider-air-canada-143', '«Планёр Гимли» — посадка Boeing 767 без капли топлива', '1983-07-23', 'Boeing 767-233 (C-GAUN)', 'Air Canada', 'ACA143', 0, 69, 'На эшелоне FL410 (12 500 м) из-за ошибки в переводе фунтов в килограммы у новейшего лайнера полностью закончилось топливо. Пилот Боб Пирсон, опытный планерист, спланировал на заброшенную военную базу Гимли, применив маневр бокового скольжения (Sideslip).', 'Человеческий фактор при переходе Канады на метрическую систему мер (заправка топливом в фунтах вместо килограммов при неисправных датчиках FQIS).', 'Внедрение обязательной перекрестной проверки количества топлива независимыми членами экипажа и инженерами перед каждым вылетом.'),
(3, 'british-airways-38-heathrow', 'Посадка до полосы Boeing 777 в Хитроу (Кристаллы льда в FOHE)', '2008-01-17', 'Boeing 777-236ER (G-YMMM)', 'British Airways', 'BAW38', 0, 152, 'При заходе на посадку в Лондоне после длительного перелета из Пекина при выпуске закрылков оба двигателя перестали реагировать на команды РУД из-за закупорки топливно-масляных теплообменников (FOHE) микрокристаллами льда. Самолет сел на траву за 300 метров до торца полосы 27L без погибших.', 'Образование ледяной каши в переохлажденном керосине во время многочасового полета над Сибирью при экстремально низких температурах за бортом (-74°C).', 'Была полностью переработана внутренняя конструкция теплообменников двигателей Rolls-Royce Trent 800 и внедрены процедуры периодического прогрева топлива на эшелоне.')
INSERT INTO `va_quizzes` (`id`, `slug`, `title`, `description`, `category`, `difficulty`, `time_limit_sec`, `reward_xp`, `badge_code`) VALUES
(1, 'ppl-aerodynamics-theory', 'Основы аэродинамики и теории полета PPL', 'Квалификационный тест на знание подъемной силы, законов Бернулли, углов атаки, сваливания и профилей крыла.', 'aerodynamics', 'cadet', 600, 150, 'quiz_ace'),
(2, 'metar-taf-weather-master', 'Метеосводки METAR и TAF: Мастер погоды', 'Проверьте навык мгновенной расшифровки видимости CAVOK, эшелонов облачности BKN/OVC, явлений погоды и сдвигов ветра.', 'weather', 'ppl', 600, 200, 'metar_master'),
(3, 'ifr-navigation-vor-ils', 'Радионавигация, схемы SID/STAR и заходы ILS', 'Экзамен для пилотов по правилам полетов по приборам: QNH/QFE, градиенты набора, минимумы CAT I/II/III.', 'navigation', 'cpl_atpl', 900, 300, 'quiz_ace'),
(4, 'aircraft-systems-hydraulics', 'Авиационные системы, гидравлика и ВСУ', 'Устройство бортовых энергосистем современных лайнеров: Fly-by-Wire, ВСУ (APU), гидросистемы Green/Blue/Yellow, аварийная турбина RAT.', 'systems', 'ppl', 600, 250, 'quiz_ace')
INSERT INTO `va_quiz_questions` (`quiz_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`) VALUES
(1, 'За счет чего формируется основная часть подъемной силы на несимметричном профиле крыла?', 'Исключительно за счет механического отбрасывания воздуха вниз нижней плоскостью', 'За счет разницы давлений: разрежения над верхней поверхностью и повышенного давления под нижней (уравнение Бернулли)', 'За счет трения молекул воздуха о лакокрасочное покрытие крыла', 'За счет избыточного давления от реактивных струй двигателей', 'b', 'Подъемная сила формируется главным образом кривизной профиля: путь воздушного потока над верхней поверхностью длиннее, скорость выше, а статическое давление ниже (разрежение), что создает подъемную силу.'),
(1, 'Что происходит с крылом при превышении критического угла атаки (Critical Angle of Attack)?', 'Самолет переходит в режим сверхзвукового разгона', 'Происходит срыв пограничного слоя с верхней поверхности крыла и аэродинамическое сваливание (Stall)', 'Подъемная сила возрастает до максимума и удерживается неограниченно долго', 'Автоматически включается максимальный реверс тяги двигателей', 'b', 'При превышении критического угла атаки (около 15°-18°) воздушный поток не может плавно огибать верхнюю кромку крыла, срывается в хаотические вихри, что приводит к резкой потере подъемной силы.'),
(2, 'Что означает международный код «CAVOK» в метеорологической сводке METAR?', 'Густой переохлажденный туман и нулевая видимость на полосе', 'Ceiling And Visibility OK: видимость более 10 км, нет облаков ниже 1500 м / MSA, нет гроз CB и опасных осадков', 'Боковой ветер с порывами свыше 30 узлов перпендикулярно оси ВПП', 'Аэродром закрыт на очистку полосы от снега и льда', 'b', 'CAVOK (Clouds And Visibility OK) свидетельствует об отличной погоде: видимость 10 км и более, отсутствие облачности ниже 5000 футов или ниже безопасной высоты в секторе, и отсутствие опасных явлений.'),
(2, 'Как расшифровывается группа ветра «24015G28KT» в коде METAR?', 'Ветер с направлением 15 градусов со скоростью 240 узлов', 'Ветер с направления 240 градусов со средней скоростью 15 узлов и порывами до 28 узлов', 'Ветер переменный от 15 до 28 узлов на высоте 2400 метров', 'Встречный ветер на полосу 24 со скоростью 15 километров в час', 'b', 'Первые три цифры (240) — магнитное направление ветра в градусах, следующие две (15) — постоянная скорость в узлах (KT), литера G (Gusts) с числом 28 — скорость порывов до 28 узлов.'),
(3, 'Что произойдет, если пилот забудет перевести шкалу высотомера с местного QNH на стандартное давление (STD 1013 гПа) при наборе эшелона?', 'Высотомер выключится и выдаст ошибку Flag Fail', 'Показания высотомера будут отличаться от фактического эшелона полета, что создаст риск опасного сближения по высоте с другими бортами', 'Самолет автоматически выполнит аварийное снижение', 'Отключится автопилот и автомат тяги', 'b', 'Выше высоты перехода (Transition Altitude) все воздушные суда обязаны выдерживать единую барометрическую шкалу 1013.25 гПа (29.92 inHg), чтобы обеспечить строгое вертикальное эшелонирование в 1000 футов (RVSM).'),
(4, 'Какую ключевую функцию выполняет аварийная ветряная турбина RAT (Ram Air Turbine)?', 'Используется для подзарядки смартфонов экипажа в кабине', 'Выпускается в набегающий воздушный поток при отказе всех двигателей для выработки гидравлического давления и электроэнергии первой категории', 'Снижает лобовое сопротивление фюзеляжа на крейсерском эшелоне', 'Служит дополнительным тормозом при посадке на короткие полосы', 'b', 'Турбина RAT автоматически или вручную выбрасывается в поток воздуха при потере всех источников электропитания или давления в гидросистемах, вращая аварийный гидронасос и генератор.');
